using ClosedXML.Excel;
using Microsoft.EntityFrameworkCore;
using QL_KhachSan.DangNhap;
using QL_KhachSan.Models;
using QL_KhachSan.SoDoPhong;
using System.Globalization;

namespace QL_KhachSan.PhieuThue;

internal sealed class FormChiTietPhieuThue : Form
{
    private readonly string _maPT; private readonly DataGridView _grid = HotelUi.Grid(); private readonly Label _heading = new();
    private sealed record Row(string MaCTDP, string MaPH, DateTime CheckIn, DateTime CheckOut, string TrangThai, decimal ThanhTien);
    public FormChiTietPhieuThue(string maPT)
    {
        _maPT = maPT; _grid.AutoGenerateColumns = false; Text = "Chi tiết phiếu thuê"; StartPosition = FormStartPosition.CenterParent; Size = new Size(1180, 650); MinimumSize = new Size(920, 500); BackColor = HotelUi.Background;
        var root = new TableLayoutPanel { Dock = DockStyle.Fill, Padding = new Padding(14), ColumnCount = 1, RowCount = 2 }; root.RowStyles.Add(new RowStyle(SizeType.Absolute, 72)); root.RowStyles.Add(new RowStyle(SizeType.Percent, 100));
        _heading.Dock = DockStyle.Fill; _heading.Font = new Font("Segoe UI", 12, FontStyle.Bold); _heading.ForeColor = HotelUi.DarkGreen; root.Controls.Add(_heading, 0, 0);
        AddText("MaCTDP", "Mã CT thuê", "MaCTDP", 14); AddText("MaPH", "Mã phòng", "MaPH", 10); AddText("CheckIn", "Nhận phòng", "CheckIn", 17, "dd/MM/yyyy HH:mm"); AddText("CheckOut", "Trả phòng", "CheckOut", 17, "dd/MM/yyyy HH:mm"); AddText("TrangThai", "Trạng thái", "TrangThai", 14); AddText("ThanhTien", "Tiền phòng", "ThanhTien", 14, "N0");
        foreach (var (name, title) in new[] { ("DichVu", "Dịch vụ"), ("Sua", "Cập nhật"), ("Huy", "Hủy"), ("ThanhToan", "Thanh toán") }) _grid.Columns.Add(new DataGridViewButtonColumn { Name = name, HeaderText = title, Text = title, UseColumnTextForButtonValue = true, FillWeight = 12, MinimumWidth = 80 });
        _grid.CellContentClick += GridClick; root.Controls.Add(_grid, 0, 1); Controls.Add(root); Load += (_, _) => LoadRows();
    }
    private void AddText(string name, string title, string prop, float weight, string? format = null) { var c = new DataGridViewTextBoxColumn { Name = name, HeaderText = title, DataPropertyName = prop, FillWeight = weight }; if (format is not null) c.DefaultCellStyle.Format = format; _grid.Columns.Add(c); }
    private void LoadRows() { try { using var db = new HotelManagementContext(); var p = db.PhieuThues.AsNoTracking().Where(x => x.MaPt == _maPT && x.DaXoa != true).Select(x => new { x.MaPt, x.MaKhNavigation.TenKh, TenNV = x.MaNvNavigation.TenNv, x.NgPt }).FirstOrDefault(); if (p is null) { MessageBox.Show("Không tìm thấy phiếu thuê."); Close(); return; } _heading.Text = $"Chi tiết phiếu thuê {p.MaPt} - {p.TenKh}\nNgày lập: {p.NgPt:dd/MM/yyyy}    Nhân viên: {p.TenNV}"; var rows = db.Ctdps.AsNoTracking().Where(x => x.MaPt == _maPT && x.DaXoa != true).OrderBy(x => x.MaCtdp).Select(x => new Row(x.MaCtdp, x.MaPh, x.CheckIn, x.CheckOut, x.TrangThai, x.ThanhTien ?? 0)).ToList(); var invoiced = db.HoaDons.AsNoTracking().Where(x => x.DaXoa != true && x.TrangThai == "Đã thanh toán").Select(x => x.MaCtdp).ToHashSet(); rows = rows.Select(x => x.TrangThai == "Đã xong" && invoiced.Contains(x.MaCTDP) ? x with { TrangThai = "Đã thanh toán" } : x).ToList(); _grid.DataSource = null; _grid.DataSource = rows; } catch (Exception ex) { MessageBox.Show("Lỗi tải chi tiết phiếu thuê: " + ex.GetBaseException().Message); } }
    private void GridClick(object? sender, DataGridViewCellEventArgs e) { if (e.RowIndex < 0 || e.ColumnIndex < 0) return; var r = _grid.Rows[e.RowIndex]; var id = r.Cells["MaCTDP"].Value?.ToString(); var room = r.Cells["MaPH"].Value?.ToString() ?? ""; var status = r.Cells["TrangThai"].Value?.ToString() ?? ""; if (string.IsNullOrWhiteSpace(id)) return; switch (_grid.Columns[e.ColumnIndex].Name) { case "DichVu": using (var f = new FormDanhSachDichVuPhongDaDung(id, room)) f.ShowDialog(this); break; case "Sua": using (var f = new FormSuaChiTietPhieuThue(id)) { if (f.ShowDialog(this) == DialogResult.OK) { } } break; case "Huy": Cancel(id, room, status); break; case "ThanhToan": Pay(id, room, status); break; default: return; } LoadRows(); }
    private void Cancel(string id, string room, string status) { if (status is "Đã thanh toán" or "Đã xong") { MessageBox.Show("Không thể hủy chi tiết đã hoàn tất."); return; } if (MessageBox.Show($"Hủy chi tiết đặt phòng {room}?", "Xác nhận", MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes) return; try { using var db = new HotelManagementContext(); using var tx = db.Database.BeginTransaction(); var c = db.Ctdps.FirstOrDefault(x => x.MaCtdp == id && x.DaXoa != true); if (c is null) return; c.DaXoa = true; var p = db.Phongs.FirstOrDefault(x => x.MaPh == room); var another = db.Ctdps.Any(x => x.MaPh == room && x.MaCtdp != id && x.DaXoa != true && (x.TrangThai == "Đã đặt" || x.TrangThai == "Đang thuê")); if (p is not null && !another && p.Ttph == "Đã đặt") p.Ttph = "Bình thường"; db.SaveChanges(); tx.Commit(); } catch (Exception ex) { MessageBox.Show("Không thể hủy: " + ex.GetBaseException().Message); } }
    private void Pay(string id, string room, string status) { if (status != "Đang thuê" && status != "Đã xong") { MessageBox.Show("Chỉ có thể thanh toán chi tiết phòng đang thuê hoặc đã hoàn tất nhưng chưa thanh toán."); return; } if (MessageBox.Show($"Xác nhận thanh toán phòng {room}?", "Xác nhận", MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes) return; try { using var db = new HotelManagementContext(); using var tx = db.Database.BeginTransaction(); var c = db.Ctdps.FirstOrDefault(x => x.MaCtdp == id && x.DaXoa != true); if (c is null) throw new InvalidOperationException("Không tìm thấy chi tiết phiếu thuê."); if (c.TrangThai != "Đang thuê" && c.TrangThai != "Đã xong") throw new InvalidOperationException("Trạng thái chi tiết đã thay đổi, hãy tải lại danh sách."); var hd = db.HoaDons.FirstOrDefault(x => x.MaCtdp == id && x.DaXoa != true); if (hd is null) { var all = db.HoaDons.Select(x => x.MaHd).ToList(); hd = new QL_KhachSan.Models.HoaDon { MaHd = NextInvoiceCode(all), MaCtdp = id, MaNv = FormDangNhap.MaNV_DangNhap, NgHd = DateTime.Now, TrangThai = "Đã thanh toán", DaXoa = false }; db.HoaDons.Add(hd); } else { hd.MaNv = FormDangNhap.MaNV_DangNhap; hd.NgHd = DateTime.Now; hd.TrangThai = "Đã thanh toán"; } c.TrangThai = "Đã thanh toán"; var p = db.Phongs.FirstOrDefault(x => x.MaPh == room); var another = db.Ctdps.Any(x => x.MaPh == room && x.MaCtdp != id && x.DaXoa != true && (x.TrangThai == "Đã đặt" || x.TrangThai == "Đang thuê")); if (p is not null && !another && (p.Ttph == "Đang thuê" || p.Ttph == "Đã đặt")) p.Ttph = "Bình thường"; db.SaveChanges(); tx.Commit(); MessageBox.Show("Thanh toán thành công và đã tạo hóa đơn."); } catch (Exception ex) { MessageBox.Show("Lỗi thanh toán: " + ex.GetBaseException().Message); } }
    internal static string NextInvoiceCode(List<string> codes) { var used = codes.Where(x => x.StartsWith("HD", StringComparison.OrdinalIgnoreCase)).Select(x => int.TryParse(x[2..], out var n) ? n : 0).ToHashSet(); var number = Enumerable.Range(1, 999).FirstOrDefault(x => !used.Contains(x)); if (number == 0) throw new InvalidOperationException("Đã hết mã hóa đơn."); return "HD" + number.ToString("D3", CultureInfo.InvariantCulture); }
}
